sys_script.script:
(function executeRule(current, previous) {
    var bookingRef = current.getValue('booking');
    var passRef = current.getValue('student_pass');

    // Auto-generate Payment ID on Insert
    if (current.operation() == 'insert' && !current.getValue('payment_id')) {
        var prefix = 'PAY-';
        var typeCode = '';

        if (bookingRef) {
            typeCode = 'BK';
        } else if (passRef) {
            typeCode = 'SP';
        } else {
            typeCode = 'GN';
        }

        // Count existing payments of this type
        var countGr = new GlideRecord('x_1877508_metro_0_metro_payment');
        countGr.addQuery('payment_id', 'STARTSWITH', prefix + typeCode);
        countGr.query();
        var count = countGr.getRowCount() + 1;

        var paddedCount = ('000' + count).slice(-3);
        current.setValue('payment_id', prefix + typeCode + '-' + paddedCount);
    }

    // Auto-fill Amount
    if (!current.getValue('amount') || current.getValue('amount') == '0') {
        if (bookingRef) {
            var bkGr = new GlideRecord('x_1877508_metro_0_metro_booking');
            if (bkGr.get(bookingRef)) {
                var fareAmount = bkGr.getValue('fare_amount');
                if (fareAmount) {
                    current.setValue('amount', fareAmount);
                }
            }
        } else if (passRef) {
            var spGr = new GlideRecord('x_1877508_metro_0_metro_student_pass');
            if (spGr.get(passRef)) {
                var passAmount = spGr.getValue('pass_amount');
                if (passAmount) {
                    current.setValue('amount', passAmount);
                }
            }
        }
    }

    // Update Payment Time on status change
    var txnStatus = current.getValue('transaction_status');
    if (txnStatus == 'success' || txnStatus == 'failed') {
        if (!previous || current.getValue('transaction_status') != previous.getValue('transaction_status')) {
            current.setValue('payment_time', new GlideDateTime());
        }
    }
})(current, previous);
